"""Lever registry: metadata for every optimization the modes compose, keyed by the switches the kit's own files set.

No values live here. The trunk switches are exported by the kit's `opt/forward/flashpairformer/env.sh` (modes.resolve() sources it);
the per-(cc | triton) row switches of the kit README (E*/T*: pad8, glue v2, MK-PF, the tri-attention tier word) and lazy init are exported by
modes.resolve() around env.sh (modes.README_ROWS). Every lever is a switch of the CLI route (`protenix pred` with the kit's
sitecustomize active); each entry names the env.sh line or kit document it was read from (code comments).
`tests/test_modes_match_env_sh.py` sources env.sh and fails when the set of variables the registry claims for a mode drifts from what
env.sh exports, and locks every README row against modes.resolve().
"""
from dataclasses import dataclass
from typing import Dict, Tuple

FORWARD = "forward"                       # opt/forward/: the kit class every lever belongs to
EXACT, TOLERANCE = "exact", "tolerance"


@dataclass(frozen=True)
class Lever:
    name: str
    cls: str                              # forward
    tier: str                             # exact | tolerance
    env_keys: Tuple[str, ...]             # the switches this lever reads (names only; values come from env.sh / modes.EXTRAS)
    description: str
    cells: str                            # the dispatch envelope the kit documents for this lever (its own cells / gates)
    probe: str = "env"                    # activation evidence: "env" (the kit reads the switch lazily) or "marker" (see stack.MARKERS)
    conditional: Tuple[str, ...] = ()     # switches env.sh exports only after a runtime probe (compute capability, installed torch)
    extra: bool = False                   # exported by modes.resolve() around env.sh (README row switches, lazy init), not by env.sh itself
    row_dependent: bool = False           # part of the arm only on the kit README rows that list one of its switches (modes.README_ROWS)
    source: str = ""                      # where the switch was read
    replaced_by: Tuple[str, ...] = ()       # levers that take this lever's slot on the rows that list them (k2b_flash_triattention -> triattn_cuda on cc 9.0): there this lever is not part of the arm (stack._classify), never a fallback
    requires: Tuple[str, ...] = ()          # levers this one modifies and cannot run without (a precision lever on a kernel lever): switched on only with them, ablated only with them (refused by name otherwise)
    words: Tuple[Tuple[str, str], ...] = ()          # (switch, word) pairs for a lever selected by the VALUE of a switch (PTX_T_ATT=native read BY env.sh; PTX_TRIMUL=exact|tier / PTX_TEMPL_TRIMUL exported by it): in_row() then requires the row / env.sh to export one of these words, not merely the switch
    subsumes: Tuple[Tuple[str, str, str], ...] = ()   # census interactions: (lever whose call site this lever takes over, that lever's counter, its expected value while this lever is on) — report.lever_lines re-bases the subsumed lever's line, never reads it as a fallback


def _lever(*a, **k) -> Lever:
    return Lever(*a, **k)


