TRIATT_STATEMENT_LEVERS = ("nomask", "blk2_chunked_exact", "blk2_chunked_k2b", "k2b_flash_triattention", "triattn_native")   # levers that live inside the block core's fused tri-attention statement (prologue -> attention core -> epilogue): on an arch listed in CELLS.json blk2_triatt_stock_arch the core runs the stock tri-attention statement and these are not part of the arm on that card
STOCK_TRIATT = "the block core runs the stock tri-attention statement on gpu_arch="   # the reason prefix for TRIATT_STATEMENT_LEVERS on such an arch (stack._classify; report.card_lever_set_line keys on it)
NOT_IN_ROW = "not in the kit README row for kernel key "   # the reason prefix when the kernel key's compositions row does not list a row-dependent lever (stack._classify; report.card_lever_set_line keys on it)


def in_row(lever: Lever, row) -> bool:
    """Whether a kit README row (modes.readme_row(): {"pre": {...}, "post": {...}}) lists one of this lever's switches."""
    vals = dict((row or {}).get("pre", {})); vals.update((row or {}).get("post", {}))
    if lever.words:
        return any(vals.get(k) == w for k, w in lever.words)
    return any(k in vals for k in lever.env_keys)
